import{_ as a,c as t,o as r,ag as i}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Location-tracking","description":"","frontmatter":{"title":"Location-tracking"},"headers":[],"relativePath":"general/location-tracking.md","filePath":"general/location-tracking.md","lastUpdated":null}'),n={name:"general/location-tracking.md"};function o(c,e,s,l,h,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="location-tracking" tabindex="-1">Location-tracking <a class="header-anchor" href="#location-tracking" aria-label="Permalink to &quot;Location-tracking&quot;">​</a></h1><h2 id="location-tracking-1" tabindex="-1">Location Tracking <a class="header-anchor" href="#location-tracking-1" aria-label="Permalink to &quot;Location Tracking&quot;">​</a></h2><p>Return to main <a href="/cybersecurity/cyber-red-teaming.html">Teaming Page</a></p><h3 id="tracking-objects" tabindex="-1">Tracking Objects <a class="header-anchor" href="#tracking-objects" aria-label="Permalink to &quot;Tracking Objects&quot;">​</a></h3><h3 id="with-some-physical-access" tabindex="-1">with Some Physical Access <a class="header-anchor" href="#with-some-physical-access" aria-label="Permalink to &quot;with Some Physical Access&quot;">​</a></h3><p>Link to Prevention, Detection, and Defense against this method: [-----</p><h4 id="airtags" tabindex="-1">Airtags <a class="header-anchor" href="#airtags" aria-label="Permalink to &quot;Airtags&quot;">​</a></h4><p>In the past, we used a magnetic square due to its size and wrapped it with black shrink wrap. Alternatively, you could use black electrical tape, but it tends to make a mess when changing the battery. Just disable the speaker 🔈, and it works great 👍. Place the Airtag behind the license plate for the best reception and security of the device.</p><ul><li></li></ul><p>Image of Airtag](/general/tracking-prevention)</p><p>Research by MITRE and the Naval Academy has significantly advanced the field, much of which is publicly available. Here are some resources and tools developed from this research:</p><ul><li><p>Initial research and tools can be found in this repository: <a href="https://github.com/mCarlG/Airtag-Research" target="_blank" rel="noreferrer">Airtag Research</a>, which includes links to academic articles like this <a href="https://dl.acm.org/doi/abs/10.1145/3463676.3485616" target="_blank" rel="noreferrer">ACM publication</a>.</p></li><li><p>Privacy concerns and device cloning are discussed in detail on Hackaday: <a href="https://hackaday.com/2022/02/22/no-privacy-cloning-the-airtag/" target="_blank" rel="noreferrer">No Privacy: Cloning the Airtag</a>.</p></li><li><p>Additional tools and projects for tracking and detecting Airtags include:</p></li><li><p>&#39; <a href="https://github.com/positive-security/find-you" target="_blank" rel="noreferrer">Find You</a> by Positive Security</p></li><li><p>&#39; <a href="https://github.com/seemoo-lab/openhaystack" target="_blank" rel="noreferrer">OpenHaystack</a> by Seemoo Lab</p></li><li><p>&#39; The latest Android versions allow Airtag scans, supplemented by apps like <a href="https://twitter.com/AirGuardAndroid" target="_blank" rel="noreferrer">AirGuard</a> for Android users.</p></li><li><p>&#39; <a href="https://github.com/skickar/CreepDetector" target="_blank" rel="noreferrer">CreepDetector</a> which is discussed in this <a href="https://securitytools.simplecast.com/episodes/creepdetector-detecting-stalkers-with-wardriving" target="_blank" rel="noreferrer">Security Tools podcast episode</a>.</p></li></ul>',12)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
